90	    /**
91	     * Immutable structured audit event emitted on owner creation. Its component order
92	     * ({@code seq}, {@code ownerId}, {@code memberId}, {@code membershipLevel},
93	     * {@code event}) is also the field order of the serialized JSON. The
94	     * {@code memberId} slot carries the owner's primary identifier.
95	     */
96	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId,
97	                                     Integer membershipLevel, String event) {
98	    }
