157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
160	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already
161	        // seen, return the owner originally created under it (200) rather than creating a
162	        // duplicate. The key is remembered only after a successful create below.
163	        String idempotencyKey = currentIdempotencyKey();
164	        if (idempotencyKey != null) {
165	            Integer existingId = idempotentCreates.get(idempotencyKey);
166	            if (existingId != null) {
167	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
168	                if (existingOwner != null) {
169	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
170	                }
171	            }
172	        }
173	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
174	        if (normalizedTelephone == null) {
175	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The telephone number is invalid");
176	        }
177	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
178	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Disposable email domains are not accepted");
179	        }
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        // The owner must supply an address in EITHER form: a non-blank structured
182	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
183	        // fields (composing line 1 with an optional line 2) and falls back to the flat
184	        // value; a blank result means neither form was provided. The composed value is
185	        // written back so the persisted flat 'address' stays consistent with it.
186	        String composedAddress = owner.getAddress();
187	        if (composedAddress == null || composedAddress.isBlank()) {
188	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An address must be supplied");
189	        }
190	        owner.setAddress(composedAddress);
191	        owner.setTelephone(normalizedTelephone);
192	        if (!owner.isPostcodeValidForCity()) {
193	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The postcode is not valid for the city");
194	        }
195	        // The household id is deterministic: it is derived purely from the owner's
196	        // (last name, postcode), so every owner at the same last name and postcode resolves
197	        // to the same value. It is assigned up front, before any duplicate detection, so the
198	        // identity key and the household check below both key off it.
199	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
200	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
201	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
202	        // identityKey (the SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName))
203	        // equals an existing owner's. Because the telephone is part of the key, two owners
204	        // sharing only a last name and postcode differ here whenever their telephone or email
205	        // differs, and so are both allowed (the second is surfaced as a soft match below). This
206	        // single identity key is now the only 409 duplicate check — the former separate
207	        // household-duplicate block keyed on the computed household id no longer applies.
208	        String identityKey = owner.getIdentityKey();
209	        if (this.clinicService.findAllOwners().stream()
210	            .filter(existing -> !existing.isDeleted())
211	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
212	            throw new ResponseStatusException(HttpStatus.CONFLICT, "An owner with the same identity already exists");
213	        }
214	        // The household id is still computed for household-size and membership-level purposes,
215	        // but sharing it no longer rejects the create.
216	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
217	        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
218	        if (ownersInCity >= 50) {
219	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The city has reached its owner capacity");
220	        }
221	        boolean capacityWarning = ownersInCity >= 40 && ownersInCity <= 49;
222	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
223	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The registration date must not be in the future");
224	        }
225	        LocalDate effectiveDate =
226	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
227	        LocalDate registrationDate = toBusinessDay(effectiveDate);
228	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
229	        if (ownersRegisteredToday >= 100) {
230	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS, "The daily owner registration limit has been reached");
231	        }
232	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
233	        HttpHeaders headers = new HttpHeaders();
234	        owner.setRegistrationDate(registrationDate);
235	        owner.setMemberId(memberId(owner));
236	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
237	        owner.setBulkSignupWarning(bulkSignupWarning);
238	        owner.setCapacityWarning(capacityWarning);
239	        // The household size (an input to the membership computation) keys off the computed
240	        // household id: this owner plus everyone already sharing it.
241	        owner.setHouseholdSize(householdMembers.size() + 1);
242	        // Level ceiling: a new owner joining a household they did not explicitly declare
243	        // may not out-rank the household. Cap the derived membership level at one above the
244	        // current maximum among the existing household members; with no existing member no
245	        // cap applies.
246	        if (!sharesHousehold && !householdMembers.isEmpty()) {
247	            int maxHouseholdLevel = householdMembers.stream()
248	                .mapToInt(Owner::getMembershipLevel)
249	                .max()
250	                .orElse(0);
251	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
252	        }
253	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
254	        // duplicate, so only a non-declared create is scored. A non-declared owner whose
255	        // identity key differs from an existing owner's but whose last name (by Soundex) and
256	        // postcode match is flagged here as a possible duplicate rather than rejected.
257	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
258	        owner.setPossibleDuplicate(possibleDuplicate != null);
259	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
260	        this.clinicService.saveOwner(owner);
261	        if (idempotencyKey != null) {
262	            idempotentCreates.put(idempotencyKey, owner.getId());
263	        }
264	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
265	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
266	        emitOwnerCreatedEvent(owner);
267	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
268	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
269	        headers.setLocation(UriComponentsBuilder.newInstance()
270	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
271	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
272	    }
