276	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
277	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
278	        if (currentOwner == null) {
279	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	        }
281	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
282	        if (normalizedTelephone == null) {
283	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The telephone number is invalid");
284	        }
285	        currentOwner.setAddress(ownerFieldsDto.getAddress());
286	        currentOwner.setCity(ownerFieldsDto.getCity());
287	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
288	        currentOwner.setLastName(ownerFieldsDto.getLastName());
289	        currentOwner.setTelephone(normalizedTelephone);
290	        currentOwner.setEmail(ownerFieldsDto.getEmail());
291	        this.clinicService.saveOwner(currentOwner);
292	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
