298	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        // Soft-delete: retain the row and flag it deleted rather than removing it. The owner
304	        // remains readable via GET, and is subsequently ignored by the create endpoint's
305	        // duplicate and identity checks.
306	        owner.setDeleted(true);
307	        this.clinicService.saveOwner(owner);
308	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
309	    }
