363	    /**
364	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
365	     * stripped. When a leading {@code '+'} and country code are present they are kept;
366	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
367	     * is dropped from the national digits. The result must be a {@code '+'} followed
368	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
369	     * is returned to signal a bad request.
370	     */
371	    /**
372	     * Build the member id for a newly created owner, formatted
373	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region derived from the
374	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
375	     * derivation the locality uses); {@code FY} is the two-digit fiscal year derived from
376	     * the (business-day-adjusted) registration date; {@code HASH8} is the first eight
377	     * upper-case hex characters of the SHA-256 of the owner's normalized telephone
378	     * concatenated with its last name (the same hash used by the region-and-hash
379	     * identity); and {@code CHK} is a single Luhn check digit computed over the digits of
380	     * {@code <REGION><FY><HASH8>}. On the rare collision with an existing owner's member
381	     * id a {@code '-<n>'} suffix is appended.
382	     */
383	    private String memberId(Owner owner) {
384	        String base = memberIdBase(owner);
385	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
386	            .map(Owner::getMemberId)
387	            .filter(java.util.Objects::nonNull)
388	            .collect(java.util.stream.Collectors.toSet());
389	        if (!existing.contains(base)) {
390	            return base;
391	        }
392	        int n = 2;
393	        while (existing.contains(base + "-" + n)) {
394	            n++;
395	        }
396	        return base + "-" + n;
397	    }
398	
399	    /**
400	     * Build the collision-free base of an owner's member id: {@code <REGION><FY><HASH8>}
401	     * followed by its single Luhn check digit. {@code FY} is the two-digit fiscal year
402	     * taken from {@link Owner#getFiscalYear()} (its {@code 'FY'} prefix stripped), which
403	     * is set by the time the member id is assigned.
404	     */
405	    private String memberIdBase(Owner owner) {
406	        String region = owner.getLocality();
407	        String fiscalYear = owner.getFiscalYear();
408	        String fy = fiscalYear == null ? "" : fiscalYear.substring(2);
409	        String hash8 = memberIdHash(owner.getTelephone(), owner.getLastName());
410	        String core = region + fy + hash8;
411	        return core + luhnCheckDigit(core);
412	    }
413	
414	    /**
415	     * Compute a single Luhn check digit (0-9) over the digits contained in {@code s};
416	     * non-digit characters are ignored and the rightmost digit is doubled first,
417	     * following the standard Luhn algorithm.
418	     */
419	    private int luhnCheckDigit(String s) {
420	        int sum = 0;
421	        boolean doubleDigit = true;
422	        for (int i = s.length() - 1; i >= 0; i--) {
423	            char c = s.charAt(i);
424	            if (c < '0' || c > '9') {
425	                continue;
426	            }
427	            int digit = c - '0';
428	            if (doubleDigit) {
429	                digit *= 2;
430	                if (digit > 9) {
431	                    digit -= 9;
432	                }
433	            }
434	            sum += digit;
435	            doubleDigit = !doubleDigit;
436	        }
437	        return (10 - (sum % 10)) % 10;
438	    }
439	
440	    /**
441	     * Emit the immutable structured {@code OWNER_CREATED} audit event for a freshly
442	     * created owner: a JSON object {@code {seq, ownerId, memberId, membershipLevel,
443	     * event}} logged to the dedicated {@code AUDIT} trail alongside the human-readable
444	     * audit line. Each event is stamped with the next value of the shared monotonic
445	     * sequence, and carries the owner's current primary identifier.
446	     */
447	    private void emitOwnerCreatedEvent(Owner owner) {
448	        OwnerCreatedEvent event = new OwnerCreatedEvent(
449	            CREATE_SEQUENCE.incrementAndGet(),
450	            owner.getId(),
451	            primaryIdentifier(owner),
452	            owner.getMembershipLevel(),
453	            "OWNER_CREATED");
454	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
455	    }
456	
457	    /**
458	     * The owner's primary identifier, as carried by the structured audit event: the
459	     * unified member id.
460	     */
461	    private String primaryIdentifier(Owner owner) {
462	        return owner.getMemberId();
463	    }
464	
465	    /**
466	     * Compute the {@code HASH8} portion of a member id: the first eight upper-case
467	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
468	     * treated as empty when {@code null}), already in their normalized forms.
469	     */
470	    private String memberIdHash(String telephone, String lastName) {
471	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
472	        try {
473	            byte[] digest = MessageDigest.getInstance("SHA-256")
474	                .digest(key.getBytes(StandardCharsets.UTF_8));
475	            StringBuilder sb = new StringBuilder();
476	            for (int i = 0; i < 4; i++) {
477	                sb.append(String.format("%02X", digest[i]));
478	            }
479	            return sb.toString();
480	        }
481	        catch (NoSuchAlgorithmException e) {
482	            throw new IllegalStateException(e);
483	        }
484	    }
