486	    /**
487	     * Count the existing owners whose city matches the given one, compared after
488	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
489	     * cap: a city that already holds this many owners is at capacity.
490	     */
491	    private long countOwnersInCity(String city) {
492	        String normalizedCity = normalizeForHousehold(city);
493	        return this.clinicService.findAllOwners().stream()
494	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
495	            .count();
496	    }
497	
498	    /**
499	     * Count the existing owners whose registration date falls on the given day. Used to
500	     * enforce the per-day create limit: once this many owners have been registered today,
501	     * the day is at capacity and further creates are rejected.
502	     */
503	    private long countOwnersRegisteredOn(LocalDate day) {
504	        return this.clinicService.findAllOwners().stream()
505	            .filter(existing -> day.equals(existing.getRegistrationDate()))
506	            .count();
507	    }
508	
509	    /**
510	     * The fixed public holidays that the business-day roll skips. A registration date
511	     * landing on one of these is treated like a weekend and advanced to the next
512	     * non-holiday business day.
513	     */
514	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
515	        LocalDate.parse("2026-01-01"),
516	        LocalDate.parse("2026-01-26"),
517	        LocalDate.parse("2026-04-25"),
518	        LocalDate.parse("2026-12-25"),
519	        LocalDate.parse("2026-12-28"));
520	
521	    /**
522	     * Roll a registration date forward to the next business day: a date falling on a
523	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
524	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
525	     */
526	    private LocalDate toBusinessDay(LocalDate date) {
527	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
528	            date = date.plusDays(1);
529	        }
530	        return date;
531	    }
532	
533	    private static boolean isWeekend(LocalDate date) {
534	        DayOfWeek dayOfWeek = date.getDayOfWeek();
535	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
536	    }
537	
538	    /**
539	     * Find the existing owners that already belong to the same household as the given
540	     * computed household id. Because the household id is derived deterministically from
541	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
542	     * that last name and postcode.
543	     */
544	    private List<Owner> findHouseholdMembers(String householdId) {
545	        if (householdId == null) {
546	            return List.of();
547	        }
548	        return this.clinicService.findAllOwners().stream()
549	            .filter(existing -> !existing.isDeleted())
550	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
551	            .toList();
552	    }
553	
554	    /**
555	     * Find an existing owner that this new owner softly duplicates: one whose last name has
556	     * the same Soundex code and whose postcode matches, but whose whole identity key differs
557	     * (an equal identity key is a hard duplicate, already rejected above with 409). Returns
558	     * the lowest-id such owner, or {@code null} when the new owner has no postcode or no soft
559	     * match exists. Owners flagged deleted are ignored.
560	     */
561	    private Owner findPossibleDuplicate(Owner owner) {
562	        String postcode = owner.getPostcode();
563	        if (postcode == null) {
564	            return null;
565	        }
566	        String soundex = Owner.soundex(owner.getLastName());
567	        String identityKey = owner.getIdentityKey();
568	        return this.clinicService.findAllOwners().stream()
569	            .filter(existing -> !existing.isDeleted())
570	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
571	                && postcode.equals(existing.getPostcode())
572	                && !identityKey.equals(existing.getIdentityKey()))
573	            .min(java.util.Comparator.comparing(Owner::getId))
574	            .orElse(null);
575	    }
576	
577	    /**
578	     * Count the existing owners that already share both the given first and last
579	     * name, compared case-insensitively. Used to populate an owner's namesake count
580	     * at creation time, reflecting how many owners with the same name existed before
581	     * this one was created.
582	     */
583	    private int countNamesakes(String firstName, String lastName) {
584	        String normalizedFirstName = normalizeName(firstName);
585	        String normalizedLastName = normalizeName(lastName);
586	        return (int) this.clinicService.findAllOwners().stream()
587	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
588	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
589	            .count();
590	    }
591	
592	    private String normalizeName(String value) {
593	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
594	    }
595	
596	    /**
597	     * Build the deterministic identifier shared by all owners of one household: the first
598	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
599	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
600	     * name and postcode resolves to the same value regardless of creation order.
601	     */
602	    private String householdId(String lastName, String postcode) {
603	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
604	        try {
605	            byte[] digest = MessageDigest.getInstance("SHA-256")
606	                .digest(key.getBytes(StandardCharsets.UTF_8));
607	            StringBuilder sb = new StringBuilder();
608	            for (int i = 0; i < 6; i++) {
609	                sb.append(String.format("%02x", digest[i]));
610	            }
611	            return sb.toString();
612	        }
613	        catch (NoSuchAlgorithmException e) {
614	            throw new IllegalStateException(e);
615	        }
616	    }
617	
618	    private String normalizeForHousehold(String value) {
619	        if (value == null) {
620	            return "";
621	        }
622	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
623	    }
624	
625	    /** True when the email's domain is on the disposable-provider blocklist. */
626	    private boolean isDisposableEmailDomain(String email) {
627	        if (email == null) {
628	            return false;
629	        }
630	        int at = email.lastIndexOf('@');
631	        if (at < 0 || at == email.length() - 1) {
632	            return false;
633	        }
634	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
635	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
636	    }
637	
638	    /**
639	     * Read the {@code Idempotency-Key} header from the current request, or {@code null}
640	     * when it is absent or blank (the generated API signature does not expose it, so it is
641	     * pulled from the bound request attributes).
642	     */
643	    private String currentIdempotencyKey() {
644	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
645	            return null;
646	        }
647	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
648	        return (key == null || key.isBlank()) ? null : key;
649	    }
650	
651	    private String normalizeTelephone(String telephone) {
652	        if (telephone == null) {
653	            return null;
654	        }
655	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
656	        String digits;
657	        if (cleaned.startsWith("+")) {
658	            digits = cleaned.substring(1);
659	        } else {
660	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
661	            digits = "61" + national;
662	        }
663	        if (!digits.matches("[0-9]{8,15}")) {
664	            return null;
665	        }
666	        if (!hasValidNationalLength(digits)) {
667	            return null;
668	        }
669	        return "+" + digits;
670	    }
671	
672	    /**
673	     * Validate the national-number length of an E.164 number (the digits, without the
674	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
675	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
676	     * codes without a known rule are accepted as-is.
677	     */
678	    private boolean hasValidNationalLength(String digits) {
679	        if (digits.startsWith("61")) {
680	            return digits.length() - 2 == 9;
681	        }
682	        if (digits.startsWith("1")) {
683	            return digits.length() - 1 == 10;
684	        }
685	        return true;
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
691	        Owner owner = this.clinicService.findOwnerById(ownerId);
692	        if (owner != null) {
693	            Pet pet = owner.getPet(petId);
694	            if (pet != null) {
695	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
696	            }
697	        }
698	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
699	    }
700	}
