96	
97	    @Column(name = "membership_level_cap")
98	    private Integer membershipLevelCap;
99	
100	    @Column(name = "possible_duplicate")
101	    private Boolean possibleDuplicate;
102	
103	    @Column(name = "possible_duplicate_of")
104	    private Integer possibleDuplicateOf;
105	
106	    @Column(name = "deleted", nullable = false)
107	    private boolean deleted = false;
108	
109	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
110	    private Set<Pet> pets;
111	
112	    /** Common street-type abbreviations expanded during address normalization. */
113	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
114	        "ST", "STREET",
115	        "RD", "ROAD",
116	        "AVE", "AVENUE");
117	
118	    /**
119	     * Second-level labels of the known disposable/throwaway email providers (the
120	     * label immediately left of the TLD, e.g. {@code mailinator} for
121	     * {@code mailinator.com}). Used to flag disposable-adjacent domains — those
122	     * sharing a provider's base name via a subdomain or a different TLD — which the
123	     * exact-match create-time blocklist does not catch.
124	     */
125	    private static final Set<String> DISPOSABLE_EMAIL_BASE_LABELS = Set.of(
126	        "mailinator", "tempmail", "guerrillamail");
127	
128	    /** Fixed city-to-region table used to derive an owner's locality. */
129	    private static final Map<String, String> CITY_REGION = Map.of(
130	        "Sydney", "NSW",
131	        "Melbourne", "VIC",
132	        "Brisbane", "QLD");
133	
134	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
135	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
136	        "NSW", new int[] {2000, 2099},
137	        "VIC", new int[] {3000, 3099},
138	        "QLD", new int[] {4000, 4099});
139	
140	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
141	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
142	        "NSW", "Australia/Sydney",
143	        "VIC", "Australia/Melbourne",
144	        "QLD", "Australia/Brisbane");
145	
146	    /**
147	     * Return the owner's address. When a structured address is supplied (a non-blank
148	     * {@code addressLine1}) it takes precedence and the value is composed as the
149	     * normalized {@code addressLine1}, with a single space and the normalized
150	     * {@code addressLine2} appended when an {@code addressLine2} is present.
151	     * Otherwise the flat {@code address} is returned, preserving backward
152	     * compatibility for owners supplied in the flat form.
153	     */
154	    public String getAddress() {
155	        if (this.addressLine1 != null && !this.addressLine1.isBlank()) {
156	            if (this.addressLine2 != null && !this.addressLine2.isBlank()) {
157	                return this.addressLine1 + " " + this.addressLine2;
158	            }
159	            return this.addressLine1;
160	        }
161	        return this.address;
162	    }
163	
164	    /**
165	     * Set the owner's flat address, normalizing it to a canonical form so it is both
166	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
167	     * internal runs of whitespace are collapsed to a single space, the value is
168	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
169	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
170	     * left as-is.
171	     */
172	    public void setAddress(String address) {
173	        this.address = normalizeAddress(address);
174	    }
175	
176	    public String getAddressLine1() {
177	        return this.addressLine1;
178	    }
179	
180	    /**
181	     * Set the first line of the owner's structured address, normalized the same way
182	     * as the flat {@link #setAddress(String)} (trimmed, whitespace collapsed,
183	     * upper-cased, street-type abbreviations expanded). A {@code null} value is left
184	     * as-is.
185	     */
186	    public void setAddressLine1(String addressLine1) {
187	        this.addressLine1 = normalizeAddress(addressLine1);
188	    }
189	
190	    public String getAddressLine2() {
191	        return this.addressLine2;
192	    }
193	
194	    /**
195	     * Set the optional second line of the owner's structured address, normalized the
196	     * same way as {@link #setAddressLine1(String)}. A {@code null} value is left
197	     * as-is.
198	     */
199	    public void setAddressLine2(String addressLine2) {
200	        this.addressLine2 = normalizeAddress(addressLine2);
201	    }
202	
203	    /**
204	     * Normalize an address string to its canonical form: trimmed, whitespace
205	     * collapsed, upper-cased, with common street-type abbreviations expanded.
206	     * Returns {@code null} for a {@code null} input; a value that is blank once
207	     * trimmed normalizes to the empty string.
208	     */
209	    public static String normalizeAddress(String address) {
210	        if (address == null) {
211	            return null;
212	        }
213	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
214	        if (collapsed.isEmpty()) {
215	            return "";
216	        }
217	        String[] tokens = collapsed.split(" ");
218	        StringBuilder sb = new StringBuilder();
219	        for (int i = 0; i < tokens.length; i++) {
220	            if (i > 0) {
221	                sb.append(' ');
222	            }
223	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
224	        }
225	        return sb.toString();
226	    }
