244	    /**
245	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
246	     * country code, a space, then the national digits grouped in threes and separated
247	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
248	     * North American country code ({@code '+1'}) is one digit; other country codes are
249	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
250	     * raw value unchanged when it is not a well-formed E.164 number.
251	     */
252	    public String getTelephoneDisplay() {
253	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
254	            return this.telephone;
255	        }
256	        String digits = this.telephone.substring(1);
257	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
258	        if (digits.length() <= countryCodeLength) {
259	            return this.telephone;
260	        }
261	        String countryCode = digits.substring(0, countryCodeLength);
262	        String national = digits.substring(countryCodeLength);
263	        StringBuilder sb = new StringBuilder("+").append(countryCode);
264	        for (int i = 0; i < national.length(); i += 3) {
265	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
266	        }
267	        return sb.toString();
268	    }
269	
270	    public String getEmail() {
271	        return this.email;
272	    }
273	
274	    /**
275	     * Set the owner's email address, normalizing it to lower case so it is both
276	     * stored and returned in a canonical form. A {@code null} value is left as-is.
277	     */
278	    public void setEmail(String email) {
279	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
280	    }
