288	    }
289	
290	    /**
291	     * Return the owner's salutation: the title and last name separated by a single
292	     * space (for example {@code 'DR who'}), or just the last name when no title was
293	     * supplied (a {@code null} or blank title).
294	     */
295	    public String getSalutation() {
296	        if (this.title == null || this.title.isBlank()) {
297	            return getLastName();
298	        }
299	        return this.title + " " + getLastName();
300	    }
