318	    /**
319	     * Return the owner's age band derived from the birth date, computed against the
320	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
321	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
322	     * either the birth date or the registration date is not set.
323	     */
324	    public String getAgeBand() {
325	        if (this.birthDate == null || this.registrationDate == null) {
326	            return null;
327	        }
328	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
329	        if (age < 18) {
330	            return "MINOR";
331	        }
332	        if (age < 65) {
333	            return "ADULT";
334	        }
335	        return "SENIOR";
336	    }
