346	    /**
347	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
348	     * is always valid (postcode is optional). When present, a postcode is valid if
349	     * the city has no known region, or if it is four digits falling within the
350	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
351	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
352	     */
353	    public boolean isPostcodeValidForCity() {
354	        if (this.postcode == null) {
355	            return true;
356	        }
357	        String region = CITY_REGION.get(this.city);
358	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
359	        if (range == null) {
360	            return true;
361	        }
362	        if (!this.postcode.matches("^[0-9]{4}$")) {
363	            return false;
364	        }
365	        int value = Integer.parseInt(this.postcode);
366	        return value >= range[0] && value <= range[1];
367	    }
368	
369	    public String getMemberId() {
370	        return this.memberId;
371	    }
372	
373	    public void setMemberId(String memberId) {
374	        this.memberId = memberId;
375	    }
376	
377	    /**
378	     * Return the owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY}
379	     * is the last two digits of the fiscal year derived from the (business-day
380	     * adjusted) registration date. The fiscal year starts on 1 July and is named
381	     * after the calendar year in which it ends, so a registration date on or after
382	     * 1 July belongs to the fiscal year ending the following calendar year (for
383	     * example {@code 2026-08-14 -> 'FY27'}), while a date before 1 July belongs to
384	     * the fiscal year ending in that same calendar year. Returns {@code null} when
385	     * the registration date is not set.
386	     */
387	    public String getFiscalYear() {
388	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
389	        if (fiscalYear == null) {
390	            return null;
391	        }
392	        return String.format("FY%02d", fiscalYear % 100);
393	    }
394	
395	    /**
396	     * Return the fiscal year (the calendar year in which the fiscal year ends) that
397	     * the given date falls in, where the fiscal year starts on 1 July, or
398	     * {@code null} when the date is {@code null}.
399	     */
400	    private static Integer fiscalYearOf(LocalDate date) {
401	        if (date == null) {
402	            return null;
403	        }
404	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
405	    }
406	
407	    public String getHouseholdId() {
408	        return this.householdId;
409	    }
410	
411	    public void setHouseholdId(String householdId) {
412	        this.householdId = householdId;
413	    }
414	
415	    public Integer getNamesakeCount() {
416	        return this.namesakeCount;
417	    }
418	
419	    /**
420	     * Return the owner's membership points, the raw score from which the
421	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
422	     * email address is present, {@code 1} when the owner has no namesakes
423	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
424	     * more, and {@code 3} when the owner's tenure (the number of fiscal years
425	     * elapsed since the registration date, the fiscal year starting on 1 July) is
426	     * at least {@code 1}.
427	     */
428	    public Integer getMembershipPoints() {
429	        int points = 0;
430	        boolean hasEmail = this.email != null && !this.email.isBlank();
431	        if (hasEmail) {
432	            points += 2;
433	        }
434	        if (this.namesakeCount != null && this.namesakeCount == 0) {
435	            points += 1;
436	        }
437	        if (this.householdSize != null && this.householdSize >= 3) {
438	            points += 2;
439	        }
440	        Integer registrationFiscalYear = fiscalYearOf(this.registrationDate);
441	        if (registrationFiscalYear != null) {
442	            int elapsedFiscalYears = fiscalYearOf(LocalDate.now()) - registrationFiscalYear;
443	            if (elapsedFiscalYears >= 1) {
444	                points += 3;
445	            }
446	        }
447	        return points;
448	    }
449	
450	    /**
451	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
452	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
453	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
454	     * {@code 4} for {@code 6} or more. When a {@code membershipLevelCap} is set,
455	     * the derived level is capped at it (a level higher than the cap is lowered to
456	     * the cap); the cap records one above the maximum level among the owner's
457	     * household members at creation time.
458	     */
459	    public Integer getMembershipLevel() {
460	        int points = getMembershipPoints();
461	        int level;
462	        if (points >= 6) {
463	            level = 4;
464	        }
465	        else if (points >= 4) {
466	            level = 3;
467	        }
468	        else if (points >= 2) {
469	            level = 2;
470	        }
471	        else {
472	            level = 1;
473	        }
474	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
475	            return this.membershipLevelCap;
476	        }
477	        return level;
478	    }
479	
480	    public Integer getMembershipLevelCap() {
481	        return this.membershipLevelCap;
482	    }
483	
484	    public void setMembershipLevelCap(Integer membershipLevelCap) {
485	        this.membershipLevelCap = membershipLevelCap;
486	    }
487	
488	    public void setNamesakeCount(Integer namesakeCount) {
489	        this.namesakeCount = namesakeCount;
490	    }
491	
492	    public Integer getHouseholdSize() {
493	        return this.householdSize;
494	    }
495	
496	    public void setHouseholdSize(Integer householdSize) {
497	        this.householdSize = householdSize;
498	    }
499	
500	    /**
501	     * Whether this owner, when created, softly matched an existing owner by
502	     * sharing the same last name and postcode but with a different telephone.
503	     * Such an owner is still created; the flag surfaces the likely duplication.
504	     */
505	    public Boolean getPossibleDuplicate() {
506	        return this.possibleDuplicate;
507	    }
508	
509	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
510	        this.possibleDuplicate = possibleDuplicate;
511	    }
512	
513	    /**
514	     * The id of the existing owner this owner softly matched on last name and
515	     * postcode (with a different telephone), or {@code null} when there is no
516	     * such match.
517	     */
518	    public Integer getPossibleDuplicateOf() {
519	        return this.possibleDuplicateOf;
520	    }
521	
522	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
523	        this.possibleDuplicateOf = possibleDuplicateOf;
524	    }
525	
526	    /**
527	     * Whether this owner has been soft-deleted. A newly created owner is not
528	     * deleted; {@code DELETE /api/owners/{id}} sets this flag rather than removing
529	     * the row, and a flagged owner is ignored by the create endpoint's duplicate
530	     * and identity checks.
531	     */
532	    public boolean isDeleted() {
533	        return this.deleted;
534	    }
535	
536	    public void setDeleted(boolean deleted) {
537	        this.deleted = deleted;
538	    }
539	
540	    /**
541	     * Whether more than 80 owners had already been registered on this owner's
542	     * registration day at the time it was created, flagging a bulk-signup surge.
543	     */
544	    public Boolean getBulkSignupWarning() {
545	        return this.bulkSignupWarning;
546	    }
547	
548	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
549	        this.bulkSignupWarning = bulkSignupWarning;
550	    }
551	
552	    /**
553	     * Whether this owner's city already held between 40 and 49 owners at the time
554	     * it was created, flagging that the city is approaching the per-city capacity
555	     * limit of 50 (at which further creates are rejected).
556	     */
557	    public Boolean getCapacityWarning() {
558	        return this.capacityWarning;
559	    }
560	
561	    public void setCapacityWarning(Boolean capacityWarning) {
562	        this.capacityWarning = capacityWarning;
563	    }
564	
565	    /**
566	     * Whether the owner's email domain is disposable-adjacent: its second-level
567	     * label (the label immediately left of the TLD) matches a known disposable
568	     * provider's base name. This catches domains the exact-match create-time
569	     * blocklist misses, such as a subdomain ({@code x.mailinator.com}) or the same
570	     * provider under a different TLD ({@code mailinator.net}). Returns {@code false}
571	     * when the email is absent or has no recognisable domain.
572	     */
573	    public boolean isDisposableAdjacentEmail() {
574	        if (this.email == null) {
575	            return false;
576	        }
577	        int at = this.email.lastIndexOf('@');
578	        if (at < 0 || at == this.email.length() - 1) {
579	            return false;
580	        }
581	        String domain = this.email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
582	        String[] labels = domain.split("\\.");
583	        if (labels.length < 2) {
584	            return false;
585	        }
586	        String secondLevel = labels[labels.length - 2];
587	        return DISPOSABLE_EMAIL_BASE_LABELS.contains(secondLevel);
588	    }
589	
590	    /**
591	     * Whether this owner should be flagged for risk review. True when any of these
592	     * hold: the owner is a possible duplicate, the email domain is
593	     * disposable-adjacent, or the owner's city is over its soft capacity (the
594	     * capacity warning is set, meaning the city already held 40 or more owners when
595	     * this one was created); otherwise false.
596	     */
597	    public Boolean getRiskFlag() {
598	        boolean possibleDuplicateMatch = Boolean.TRUE.equals(this.possibleDuplicate);
599	        boolean overSoftCapacity = Boolean.TRUE.equals(this.capacityWarning);
600	        return possibleDuplicateMatch || overSoftCapacity || isDisposableAdjacentEmail();
601	    }
602	
603	    /**
604	     * Return the owner's locality (region), preferring the postcode: when the
605	     * postcode is present and falls within a known region's inclusive range
606	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
607	     * region is returned. Otherwise the value falls back to the fixed
608	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
609	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
610	     * table. This yields the same region for known cities but disambiguates
611	     * cities that share a name.
612	     */
613	    public String getLocality() {
614	        String regionFromPostcode = regionForPostcode();
615	        if (regionFromPostcode != null) {
616	            return regionFromPostcode;
617	        }
618	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
619	    }
620	
621	    /**
622	     * Return the owner's IANA timezone, derived from the locality/region via the
623	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
624	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
625	     * {@code null} when the region is not in the table.
626	     */
627	    public String getTimezone() {
628	        return REGION_TIMEZONE.get(getLocality());
629	    }
630	
631	    /**
632	     * Look up the region whose inclusive postcode range contains this owner's
633	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
634	     * known range.
635	     */
636	    private String regionForPostcode() {
637	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
638	            return null;
639	        }
640	        int value = Integer.parseInt(this.postcode);
641	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
642	            int[] range = entry.getValue();
643	            if (value >= range[0] && value <= range[1]) {
644	                return entry.getKey();
645	            }
646	        }
647	        return null;
648	    }
649	
650	    /**
651	     * Return the owner's preferred contact channel, derived from the stored
652	     * contact details: {@code 'EMAIL'} when an email address is present,
653	     * otherwise {@code 'PHONE'}.
654	     */
655	    public String getContactPreference() {
656	        boolean hasEmail = this.email != null && !this.email.isBlank();
657	        return hasEmail ? "EMAIL" : "PHONE";
658	    }
659	
660	    /**
661	     * Return the owner's marketing segment, formatted {@code '<TIER>_<AREA>'}.
662	     * {@code TIER} is {@code 'PREMIUM'} when the {@link #getMembershipLevel()
663	     * membership level} is {@code 3} or more, otherwise {@code 'STANDARD'}.
664	     * {@code AREA} is {@code 'METRO'} when the {@link #getLocality() locality}
665	     * is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
666	     * {@code 'REGIONAL'}.
667	     */
668	    public String getOwnerSegment() {
669	        Integer membershipLevel = getMembershipLevel();
670	        String tier = (membershipLevel != null && membershipLevel >= 3) ? "PREMIUM" : "STANDARD";
671	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
672	        return tier + "_" + area;
673	    }
674	
675	    /**
676	     * Return the owner's derived identity key, which consolidates all duplicate
677	     * detection into a single value: the SHA-256 digest, rendered as 64 lower-case
678	     * hex characters, of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
679	     * The telephone and email are already stored in their normalized (E.164 /
680	     * lower-cased) forms; a missing email contributes an empty segment and the last
681	     * name is reduced to its Soundex code. A create is rejected only when a new
682	     * owner's whole identity key equals an existing owner's.
683	     */
684	    public String getIdentityKey() {
685	        String telephonePart = this.telephone == null ? "" : this.telephone;
686	        String emailPart = (this.email == null) ? "" : this.email.toLowerCase(Locale.ROOT);
687	        String soundexPart = soundex(getLastName());
688	        String key = telephonePart + "|" + emailPart + "|" + soundexPart;
689	        try {
690	            byte[] digest = MessageDigest.getInstance("SHA-256")
691	                .digest(key.getBytes(StandardCharsets.UTF_8));
692	            StringBuilder sb = new StringBuilder(digest.length * 2);
693	            for (byte b : digest) {
694	                sb.append(String.format("%02x", b));
695	            }
696	            return sb.toString();
697	        }
698	        catch (NoSuchAlgorithmException e) {
699	            throw new IllegalStateException(e);
700	        }
701	    }
702	
703	    /**
704	     * Compute the American Soundex code of the given name: its first letter followed
705	     * by three digits derived from the remaining consonants (vowels act as separators,
706	     * {@code H} and {@code W} are transparent, and adjacent equal codes collapse),
707	     * zero-padded and truncated to four characters. Returns an empty string when the
708	     * name is {@code null} or holds no letters.
709	     */
710	    public static String soundex(String name) {
711	        if (name == null) {
712	            return "";
713	        }
714	        StringBuilder letters = new StringBuilder();
715	        for (int i = 0; i < name.length(); i++) {
716	            char c = name.charAt(i);
717	            if (Character.isLetter(c)) {
718	                letters.append(Character.toUpperCase(c));
719	            }
720	        }
721	        if (letters.length() == 0) {
722	            return "";
723	        }
724	        StringBuilder code = new StringBuilder();
725	        code.append(letters.charAt(0));
726	        char prevDigit = soundexDigit(letters.charAt(0));
727	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
728	            char c = letters.charAt(i);
729	            if (c == 'H' || c == 'W') {
730	                continue;
731	            }
732	            char digit = soundexDigit(c);
733	            if (digit != '0' && digit != prevDigit) {
734	                code.append(digit);
735	            }
736	            prevDigit = digit;
737	        }
738	        while (code.length() < 4) {
739	            code.append('0');
740	        }
741	        return code.toString();
742	    }
743	
744	    private static char soundexDigit(char c) {
745	        switch (c) {
746	            case 'B': case 'F': case 'P': case 'V':
747	                return '1';
748	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
749	                return '2';
750	            case 'D': case 'T':
751	                return '3';
752	            case 'L':
753	                return '4';
754	            case 'M': case 'N':
755	                return '5';
756	            case 'R':
757	                return '6';
758	            default:
759	                return '0';
760	        }
761	    }
762	
763	    protected Set<Pet> getPetsInternal() {
764	        if (this.pets == null) {
765	            this.pets = new HashSet<>();
766	        }
767	        return this.pets;
768	    }
769	
770	    protected void setPetsInternal(Set<Pet> pets) {
771	        this.pets = pets;
772	    }
773	
774	    public List<Pet> getPets() {
775	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
776	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
777	        return Collections.unmodifiableList(sortedPets);
778	    }
779	
780	    public void setPets(List<Pet> pets) {
781	        this.pets = new HashSet<>(pets);
782	    }
783	
784	    public void addPet(Pet pet) {
785	        getPetsInternal().add(pet);
786	        pet.setOwner(this);
787	    }
788	
789	    /**
790	     * Return the Pet with the given name, or null if none found for this Owner.
791	     *
792	     * @param name to test
793	     * @return true if pet name is already in use
794	     */
795	    public Pet getPet(String name) {
796	        return getPet(name, false);
797	    }
798	
799	    /**
800	     * Return the Pet with the given name, or null if none found for this Owner.
801	     *
802	     * @param name to test
803	     * @return true if pet name is already in use
804	     */
805	    public Pet getPet(String name, boolean ignoreNew) {
806	        name = name.toLowerCase();
807	        for (Pet pet : getPetsInternal()) {
808	            if (!ignoreNew || !pet.isNew()) {
809	                String compName = pet.getName();
810	                compName = compName.toLowerCase();
811	                if (compName.equals(name)) {
812	                    return pet;
813	                }
814	            }
815	        }
816	        return null;
817	    }
818	
819	    public Pet getPet(Integer petId) {
820	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
821	    }
822	
823	    @Override
824	    public String toString() {
825	        return new ToStringCreator(this)
826	
827	            .append("id", this.getId())
828	            .append("new", this.isNew())
829	            .append("lastName", this.getLastName())
830	            .append("firstName", this.getFirstName())
831	            .append("address", this.address)
832	            .append("city", this.city)
833	            .append("telephone", this.telephone)
834	            .append("email", this.email)
835	            .toString();
836	    }
837	}
